def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = []
    op = []
    opp_c = 0
    for a, b in history:
        my.append(a)
        op.append(b)
        if b == 'C':
            opp_c += 1

    opp_d = n - opp_c

    resp_D = 0
    punished_D = 0
    for i in range(1, n):
        if my[i - 1] == 'D':
            resp_D += 1
            if op[i] == 'D':
                punished_D += 1

    recent10_d = 0
    start = n - 10
    if start < 0:
        start = 0
    for i in range(start, n):
        if op[i] == 'D':
            recent10_d += 1

    recent_punished = 0
    startp = n - 10
    if startp < 1:
        startp = 1
    for i in range(startp, n):
        if my[i - 1] == 'D' and op[i] == 'D':
            recent_punished += 1

    run_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            run_c += 1
        else:
            break

    run_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            run_d += 1
        else:
            break

    last_m = my[-1]
    last_o = op[-1]
    coop_rate = opp_c / n
    punish = punished_D / resp_D if resp_D > 0 else 0.0
    known_nonpunisher = resp_D > 0 and punished_D == 0

    if n < 10:
        if opp_c == 0:
            return 'D'
        if last_o == 'D' and (run_d >= 2 or opp_d >= 3):
            return 'D'
        return 'C'

    if opp_c == n:
        if resp_D == 0:
            if last_m == 'D' or n < 12:
                return 'C'
            return 'D'
        if punished_D == 0:
            return 'D'
        return 'C'

    if opp_d * 10 >= n * 6 or run_d >= 5 or (n >= 12 and recent10_d >= 8):
        if last_o == 'C' and last_m == 'D' and run_c >= 3 and coop_rate >= 0.45:
            return 'C'
        if last_o == 'C' and last_m == 'C' and run_c >= 8 and coop_rate >= 0.45:
            return 'C'
        return 'D'

    if last_o == 'C':
        if last_m == 'D':
            if known_nonpunisher:
                return 'D'
            if resp_D >= 1 and recent_punished == 0 and coop_rate >= 0.6:
                if rng.random() < 0.6:
                    return 'D'
            if resp_D >= 2 and punish <= 0.35 and recent_punished == 0 and coop_rate >= 0.55:
                if rng.random() < 0.4:
                    return 'D'
            return 'C'
        else:
            if known_nonpunisher and coop_rate >= 0.55:
                return 'D'
            if resp_D >= 2 and punish <= 0.35 and recent_punished == 0 and run_c >= 12 and coop_rate >= 0.6:
                if rng.random() < 0.35:
                    return 'D'
            if resp_D == 0 and last_m != 'D' and run_c >= 15 and coop_rate >= 0.8 and opp_d <= max(2, n // 10) and n < 90:
                return 'D'
            if recent_punished == 0 and resp_D > 0 and run_c >= 30 and coop_rate >= 0.75 and punish <= 0.5 and n < 90:
                if rng.random() < 0.12:
                    return 'D'
            return 'C'

    if last_m == 'D':
        if known_nonpunisher:
            return 'D'
        if coop_rate >= 0.55 and run_d <= 4 and recent10_d <= 6:
            if rng.random() < (0.7 if run_d <= 2 else 0.55):
                return 'C'
        if coop_rate < 0.4 or recent10_d >= 7 or run_d >= 5:
            return 'D'
        if rng.random() < 0.45:
            return 'C'
        return 'D'

    if n >= 2 and my[-2] == 'D':
        if run_d == 1 and coop_rate >= 0.5:
            return 'C'
        if run_d <= 2 and coop_rate >= 0.6 and rng.random() < 0.7:
            return 'C'
        return 'D'

    if coop_rate >= 0.75 and run_d == 1 and recent10_d <= 2 and rng.random() < 0.2:
        return 'C'

    return 'D'
